    y = np.random.RandomState(1).rand(shape[0]).astype(np.float32)
    try:
        model = RidgeCV(
            alphas=np.array([0.1, 1.0, 10.0], dtype=np.float32),
            gcv_mode='svd',
        )
        model.fit(X, y)
        results[label] = {
            'alpha_': model.alpha_,
            'coef_': model.coef_,
            'intercept_': model.intercept_,
